<h1><?= te('Offboarding') ?></h1><p class="sub"><?= te('Track handover and return tasks before closing an assignment. Earned wages remain separate from operational closure.') ?></p>
<?php if(!$own): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="requirement"><h2><?= te('Project exit checklist') ?></h2><label><?= te('Title') ?><input name="title" required maxlength="190"></label><label><?= te('Instructions') ?><textarea name="instructions" maxlength="4000"></textarea></label><button class="btn"><?= te('Add requirement') ?></button></form><?php endif; ?>
<?php foreach($tasks as $task): ?><div class="card"><h2><?= e($task['full_name'].' · '.$task['title']) ?></h2><p><?= e($task['project']) ?> · <?= te($task['status']??'pending') ?></p><p><?= e($task['instructions']) ?></p><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="submit"><input type="hidden" name="placement_id" value="<?= (int)$task['placement_id'] ?>"><input type="hidden" name="requirement_id" value="<?= (int)$task['requirement_id'] ?>"><textarea name="response" required maxlength="4000"><?= e($task['response']) ?></textarea><button class="btn"><?= te('Submit for review') ?></button></form><?php if(!$own&&$task['status']==='submitted'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review"><input type="hidden" name="placement_id" value="<?= (int)$task['placement_id'] ?>"><input type="hidden" name="requirement_id" value="<?= (int)$task['requirement_id'] ?>"><select name="status"><option value="approved"><?= te('Approved') ?></option><option value="rejected"><?= te('Rejected') ?></option></select><button class="btn ghost"><?= te('Review') ?></button></form><?php endif; ?></div><?php endforeach; ?>

<?php if(!$own)echo page_controls($page,count($tasks)); ?>
